# -*- coding: utf-8 -*-
"""Propagate the LiDAR 2.0 (Benes_32x32 = 1,024 net) correction across docs."""
import re

def patch(path, pairs, required=True):
    t = open(path, encoding='utf-8').read()
    orig = t
    for old, new in pairs:
        if old in t:
            t = t.replace(old, new, 1)
        elif required:
            print('  MISS in', path, ':', old[:70])
    open(path, 'w', encoding='utf-8').write(t)
    print(path, len(orig), '->', len(t))

